static long long nowms(){return chrono::duration_cast<chrono::milliseconds>(Clock::now().time_since_epoch()).count();}
struct Config {string listen,root,origin,auth; int maxconn,header,ht,idle,wt,maxreq,depth,at; sockaddr_storage la{},oa{},aa{}; socklen_t ll=0,ol=0,al=0; int rootfd=-1;} cfg;
static bool num(const string&s, unsigned long long &v){if(s.empty())return false;v=0;for(unsigned char c:s){if(c<'0'||c>'9'||v>(ULLONG_MAX-(c-'0'))/10)return false;v=v*10+c-'0';}return true;}
static string trim(string s){size_t a=s.find_first_not_of(" \t\r\n"),b=s.find_last_not_of(" \t\r\n");return a==string::npos?"":s.substr(a,b-a+1);}
static bool addr(const string&s,sockaddr_storage &a,socklen_t &l){size_t p=s.rfind(':');if(p==string::npos||p==0||p+1==s.size())return false;string h=s.substr(0,p),port=s.substr(p+1);if(h.size()>2&&h.front()=='['&&h.back()==']')h=h.substr(1,h.size()-2);unsigned long long n;if(!num(port,n)||n==0||n>65535)return false;addrinfo hint{},*res=nullptr;hint.ai_socktype=SOCK_STREAM;hint.ai_family=AF_UNSPEC;hint.ai_flags=AI_NUMERICSERV; if(getaddrinfo(h.c_str(),port.c_str(),&hint,&res))return false;bool ok=false;for(auto q=res;q;q=q->ai_next)if(q->ai_addrlen<=sizeof(a)&&(q->ai_family==AF_INET||q->ai_family==AF_INET6)){memcpy(&a,q->ai_addr,q->ai_addrlen);l=q->ai_addrlen;ok=true;break;}freeaddrinfo(res);return ok;}
static bool config(const char*path){ifstream f(path);if(!f)return false;map<string,string> m;string s;set<string> keys={"listen","root","max_connections","header_bytes","header_timeout_ms","idle_timeout_ms","write_timeout_ms","max_requests","pipeline_depth","origin_address","auth_address","auth_timeout_ms"};while(getline(f,s)){s=trim(s);if(s.empty()||s[0]=='#')continue;auto p=s.find('=');if(p==string::npos)return false;string k=trim(s.substr(0,p)),v=trim(s.substr(p+1));if(!keys.count(k)||m.count(k)||v.empty())return false;m[k]=v;}if(m.size()!=keys.size())return false;auto get=[&](const char*k,int &n){unsigned long long v;if(!num(m[k],v)||v==0||v>INT_MAX)return false;n=(int)v;return true;};cfg.listen=m["listen"];cfg.root=m["root"];cfg.origin=m["origin_address"];cfg.auth=m["auth_address"];if(cfg.root.empty()||cfg.root[0]!='/'||!get("max_connections",cfg.maxconn)||!get("header_bytes",cfg.header)||!get("header_timeout_ms",cfg.ht)||!get("idle_timeout_ms",cfg.idle)||!get("write_timeout_ms",cfg.wt)||!get("max_requests",cfg.maxreq)||!get("pipeline_depth",cfg.depth)||!get("auth_timeout_ms",cfg.at))return false;struct stat st;if(stat(cfg.root.c_str(),&st)||!S_ISDIR(st.st_mode))return false;cfg.rootfd=open(cfg.root.c_str(),O_PATH|O_DIRECTORY|O_CLOEXEC);return cfg.rootfd>=0&&addr(cfg.listen,cfg.la,cfg.ll)&&addr(cfg.origin,cfg.oa,cfg.ol)&&addr(cfg.auth,cfg.aa,cfg.al);}
static string lower(string s){for(char &c:s)if(c>='A'&&c<='Z')c+=32;return s;}
static bool tokenchar(unsigned char c){return (c>='0'&&c<='9')||(c>='A'&&c<='Z')||(c>='a'&&c<='z')||strchr("!#$%&'*+-.^_`|~",c);}
static string strip(const string&s){size_t a=0,b=s.size();while(a<b&&(s[a]==' '||s[a]=='\t'))a++;while(b>a&&(s[b-1]==' '||s[b-1]=='\t'))b--;return s.substr(a,b-a);}
static bool utf8(const string&s){for(size_t i=0;i<s.size();){unsigned char c=s[i++];if(c<0x80)continue;int n;unsigned v,min;if(c>=0xc2&&c<=0xdf){n=1;v=c&31;min=0x80;}else if(c>=0xe0&&c<=0xef){n=2;v=c&15;min=0x800;}else if(c>=0xf0&&c<=0xf4){n=3;v=c&7;min=0x10000;}else return false;if(i+n>s.size())return false;while(n--){unsigned char d=s[i++];if((d&0xc0)!=0x80)return false;v=(v<<6)|(d&63);}if(v<min||v>0x10ffff||(v>=0xd800&&v<=0xdfff))return false;}return true;}
static int hex(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
static bool pathdecode(const string&t,string &path){if(t.empty()||t[0]!='/'||t.find('#')!=string::npos)return false;size_t end=t.find('?');if(end==string::npos)end=t.size();path.clear();for(size_t i=0;i<end;i++){unsigned char c=t[i];if(c=='%'){if(i+2>=end||hex(t[i+1])<0||hex(t[i+2])<0)return false;c=(hex(t[i+1])<<4)|hex(t[i+2]);i+=2;}if(c==0||c=='\\')return false;path.push_back(c);}return utf8(path);}
struct Header {string name,value;};
struct Request {string method,target,version,path,host;vector<Header> headers;set<string> hop;bool close=false,head=false;};
struct Client {int fd=-1;uint64_t id=0;string input,output;size_t outpos=0;int state=0,requests=0,file=-1;off_t fileoff=0;unsigned long long fileleft=0;bool close=false,done=false;int up=-1;Request req;long long deadline=0,write_deadline=0;};
struct Up {int fd=-1;uint64_t id=0;Client*c=nullptr;bool auth=false,connecting=true,parsed=false,reused=false,reusable=false;string send,buf;size_t sent=0;unsigned long long remain=0;long long deadline=0;};
struct Idle {int fd;long long since;}; static vector<Idle> authpool,originpool;
static int getidle(bool auth){auto &pool=auth?authpool:originpool;while(!pool.empty()){Idle x=pool.back();pool.pop_back();char c;ssize_t n=recv(x.fd,&c,1,MSG_PEEK|MSG_DONTWAIT);if(nowms()-x.since<2000&&n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return x.fd;close(x.fd);}return -1;}
static void cleanpool(vector<Idle>&pool,long long now){size_t j=0;for(auto x:pool){if(now-x.since>=2000)close(x.fd);else pool[j++]=x;}pool.resize(j);}
static int ep;static uint64_t seq=1;struct Node{bool client;void*p;};static unordered_map<uint64_t,Node> nodes;static unordered_map<int,Client*> clients;static unordered_map<int,Up*> ups;
static void regfd(int fd,uint64_t id,uint32_t events){epoll_event e{};e.events=events;e.data.u64=id;epoll_ctl(ep,EPOLL_CTL_ADD,fd,&e);}
static void modfd(int fd,uint64_t id,uint32_t events){epoll_event e{};e.events=events;e.data.u64=id;epoll_ctl(ep,EPOLL_CTL_MOD,fd,&e);}
static void closeup(Up*u){if(!u)return;epoll_ctl(ep,EPOLL_CTL_DEL,u->fd,nullptr);nodes.erase(u->id);ups.erase(u->fd);close(u->fd);if(u->c&&u->c->up==u->fd)u->c->up=-1;delete u;}
static void recycleup(Up*u){Client*c=u->c;auto &pool=u->auth?authpool:originpool;if(!u->reusable||!u->buf.empty()||pool.size()>=4096){closeup(u);return;}epoll_ctl(ep,EPOLL_CTL_DEL,u->fd,nullptr);nodes.erase(u->id);ups.erase(u->fd);if(c&&c->up==u->fd)c->up=-1;pool.push_back({u->fd,nowms()});delete u;}
static void closeclient(Client*c){if(c->up>=0){auto it=ups.find(c->up);if(it!=ups.end())closeup(it->second);}if(c->file>=0)close(c->file);epoll_ctl(ep,EPOLL_CTL_DEL,c->fd,nullptr);nodes.erase(c->id);clients.erase(c->fd);close(c->fd);delete c;}
static void updateup(Up*u){uint32_t e=EPOLLRDHUP;if(u->connecting||u->sent<u->send.size())e|=EPOLLOUT;else if(u->auth||u->c->output.size()-u->c->outpos<131072)e|=EPOLLIN;modfd(u->fd,u->id,e);}
static void updateclient(Client*c){uint32_t e=EPOLLRDHUP;if(c->state==0)e|=EPOLLIN;if(c->outpos<c->output.size()||c->fileleft)e|=EPOLLOUT;modfd(c->fd,c->id,e);if(c->up>=0){auto it=ups.find(c->up);if(it!=ups.end())updateup(it->second);}}
static string reason(int code){switch(code){case 200:return "OK";case 400:return "Bad Request";case 401:return "Unauthorized";case 403:return "Forbidden";case 404:return "Not Found";case 405:return "Method Not Allowed";case 431:return "Request Header Fields Too Large";case 502:return "Bad Gateway";case 503:return "Service Unavailable";default:return "Response";}}
static void queuehead(Client*c,int status,unsigned long long length,const string&extra=""){c->output+="HTTP/1.1 "+to_string(status)+" "+reason(status)+"\r\nContent-Length: "+to_string(length)+"\r\nConnection: "+(c->close?string("close"):string("keep-alive"))+"\r\n"+extra+"\r\n";c->write_deadline=nowms()+cfg.wt;}
static void errorresp(Client*c,int status,bool force=false){if(force)c->close=true;c->state=3;c->done=true;queuehead(c,status,0);}
static void tokens(const string&v,set<string>&out){size_t p=0;while(p<=v.size()){size_t q=v.find(',',p);if(q==string::npos)q=v.size();string t=lower(strip(v.substr(p,q-p)));if(!t.empty())out.insert(t);if(q==v.size())break;p=q+1;}}
static int parse_request(const string&raw,Request&r){size_t e=raw.find("\r\n");if(e==string::npos)return 400;string line=raw.substr(0,e);size_t a=line.find(' '),b=a==string::npos?string::npos:line.find(' ',a+1);if(a==string::npos||b==string::npos||a==0||b==a+1||line.find(' ',b+1)!=string::npos)return 400;r.method=line.substr(0,a);r.target=line.substr(a+1,b-a-1);r.version=line.substr(b+1);for(unsigned char c:r.method)if(!tokenchar(c))return 400;for(unsigned char c:r.target)if(c<=32||c==127)return 400;if(r.version!="HTTP/1.1"&&r.version!="HTTP/1.0")return 400;if(!pathdecode(r.target,r.path))return 400;int hosts=0,cls=0;unsigned long long cl=0;bool te=false;set<string> conn;size_t p=e+2;while(p<raw.size()){size_t q=raw.find("\r\n",p);if(q==string::npos)return 400;if(q==p)break;string l=raw.substr(p,q-p);if(l.empty()||l[0]==' '||l[0]=='\t')return 400;size_t k=l.find(':');if(k==string::npos||k==0)return 400;for(size_t i=0;i<k;i++)if(!tokenchar((unsigned char)l[i]))return 400;string name=lower(l.substr(0,k)),v=strip(l.substr(k+1));for(unsigned char c:v)if(c==0||c=='\r'||c=='\n')return 400;r.headers.push_back({name,v});if(name=="host"){hosts++;r.host=v;}if(name=="content-length"){cls++;if(!num(v,cl))return 400;}if(name=="transfer-encoding")te=true;if(name=="connection")tokens(v,conn);p=q+2;}if(te||cls>1||(cls==1&&cl!=0))return 400;r.hop=conn;r.close=r.version=="HTTP/1.0"||conn.count("close");r.head=r.method=="HEAD";if(r.method!="GET"&&r.method!="HEAD")return 405;if(r.target.rfind("/gateway/",0)==0&&(hosts!=1||r.host.empty()))return 400;return 0;}
static int openfile(const string&path,int &fd,unsigned long long &size){if(path.empty()||path[0]!='/')return 400;vector<string> parts;size_t p=1;while(p<=path.size()){size_t q=path.find('/',p);if(q==string::npos)q=path.size();string s=path.substr(p,q-p);if(s=="..")return 403;if(!s.empty()&&s!=".")parts.push_back(s);if(q==path.size())break;p=q+1;}if(parts.empty())return 403;int dir=dup(cfg.rootfd);if(dir<0)return 403;for(size_t i=0;i<parts.size();i++){bool last=i+1==parts.size();int x=openat(dir,parts[i].c_str(),O_PATH|O_NOFOLLOW|O_CLOEXEC);if(x<0){int e=errno;close(dir);return e==ENOENT||e==ENOTDIR?404:403;}struct stat st;if(fstat(x,&st)){close(x);close(dir);return 403;}if(S_ISLNK(st.st_mode)){close(x);close(dir);return 403;}if(!last){close(dir);dir=x;if(!S_ISDIR(st.st_mode)){close(dir);return 404;}continue;}if(!S_ISREG(st.st_mode)){close(x);close(dir);return 403;}if(path.back()=='/'){close(x);close(dir);return 403;}string proc="/proc/self/fd/"+to_string(x);fd=open(proc.c_str(),O_RDONLY|O_CLOEXEC|O_NONBLOCK);close(x);close(dir);if(fd<0)return 403;if(fstat(fd,&st)||!S_ISREG(st.st_mode)||st.st_size<0){close(fd);fd=-1;return 403;}size=st.st_size;return 200;}close(dir);return 404;}
static bool startup(Client*c,bool auth){auto &a=auth?cfg.aa:cfg.oa;socklen_t l=auth?cfg.al:cfg.ol;int fd=getidle(auth);bool reused=fd>=0;int r=0;if(!reused){fd=socket(a.ss_family,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(fd<0)return false;r=connect(fd,(sockaddr*)&a,l);if(r<0&&errno!=EINPROGRESS){close(fd);return false;}}Up*u=new Up;u->fd=fd;u->id=seq++;u->c=c;u->auth=auth;u->reused=reused;u->connecting=(r<0);u->deadline=nowms()+(auth?cfg.at:cfg.wt);Request &q=c->req;if(auth){u->send="GET /authorize HTTP/1.1\r\nHost: "+q.host+"\r\nX-Original-URI: "+q.target+"\r\n";for(auto &h:q.headers)if(h.name=="authorization")u->send+="Authorization: "+h.value+"\r\n";}else{u->send=q.method+" "+q.target.substr(8)+" HTTP/1.1\r\nHost: "+q.host+"\r\n";static set<string> banned={"host","authorization","connection","proxy-connection","keep-alive","transfer-encoding","te","trailer","upgrade","content-length","proxy-authorization"};for(auto &h:q.headers)if(!banned.count(h.name)&&!q.hop.count(h.name))u->send+=h.name+": "+h.value+"\r\n";}u->send+="Content-Length: 0\r\nConnection: keep-alive\r\n\r\n";c->up=fd;c->state=auth?1:2;ups[fd]=u;nodes[u->id]={false,u};regfd(fd,u->id,EPOLLOUT|EPOLLRDHUP);return true;}
static void handle_request(Client*c,const string&raw){c->req=Request{};int status=parse_request(raw,c->req);c->requests++;c->close=c->req.close||c->requests>=cfg.maxreq;if(status){errorresp(c,status,status!=405);return;}if(c->req.target.rfind("/gateway/",0)==0){if(!startup(c,true))errorresp(c,503);return;}int fd=-1;unsigned long long size=0;status=openfile(c->req.path,fd,size);if(status!=200){errorresp(c,status);return;}c->state=3;c->done=true;queuehead(c,200,size,"Content-Type: application/octet-stream\r\n");if(c->req.head||!size)close(fd);else{c->file=fd;c->fileleft=size;c->fileoff=0;}}
static bool badpartial(const string&s){for(size_t i=0;i<s.size();i++){if(s[i]==0)return true;if(s[i]=='\n'&&(i==0||s[i-1]!='\r'))return true;if(s[i]=='\r'&&i+1<s.size()&&s[i+1]!='\n')return true;}return false;}
static bool drive(Client*c){for(;;){if(c->state==0){size_t end=c->input.find("\r\n\r\n");size_t check=end==string::npos?c->input.size():end+4;if(badpartial(c->input.substr(0,check))){c->close=true;errorresp(c,400,true);break;}if(end==string::npos){if(c->input.size()>(size_t)cfg.header){c->close=true;errorresp(c,431,true);}break;}if(end+4>(size_t)cfg.header){c->close=true;errorresp(c,431,true);break;}string raw=c->input.substr(0,end+4);c->input.erase(0,end+4);handle_request(c,raw);break;}if(c->state==3&&c->done&&c->outpos==c->output.size()&&c->fileleft==0){if(c->close){closeclient(c);return false;}c->state=0;c->output.clear();c->outpos=0;c->done=false;c->deadline=nowms()+(c->input.empty()?cfg.idle:cfg.ht);continue;}break;}updateclient(c);return true;}
