static bool consume_up(Up*u){Client*c=u->c;if(!u->parsed){if(!parse_up_headers(u))return false;}if(u->parsed){size_t n=(size_t)min<unsigned long long>(u->remain,u->buf.size());if(n){if(c->outpos){c->output.erase(0,c->outpos);c->outpos=0;}c->output.append(u->buf.data(),n);u->remain-=n;u->buf.erase(0,n);c->write_deadline=nowms()+cfg.wt;}if(u->remain==0){recycleup(u);c->done=true;drive(c);return false;}updateclient(c);}return true;}
static void upevent(Up*u,uint32_t ev){if(u->connecting){int er=0;socklen_t z=sizeof(er);if(getsockopt(u->fd,SOL_SOCKET,SO_ERROR,&er,&z)||er){upfail(u);return;}u->connecting=false;}while(u->sent<u->send.size()){ssize_t n=send(u->fd,u->send.data()+u->sent,u->send.size()-u->sent,MSG_NOSIGNAL);if(n>0){u->sent+=n;if(!u->auth)u->deadline=nowms()+cfg.wt;continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK)){updateup(u);return;}upfail(u);return;}char buf[32768];for(;;){if(!u->auth&&u->parsed&&u->c->output.size()-u->c->outpos>=131072)break;ssize_t n=recv(u->fd,buf,sizeof(buf),0);if(n>0){u->buf.append(buf,n);if(!u->auth)u->deadline=nowms()+cfg.wt;if(!consume_up(u))return;continue;}if(n==0){upfail(u);return;}if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK)break;upfail(u);return;}updateup(u);}
static void cliente(Client*c,uint32_t ev){if(ev&EPOLLIN){char buf[16384];for(;;){ssize_t n=recv(c->fd,buf,sizeof(buf),0);if(n>0){if(c->input.empty())c->deadline=nowms()+cfg.ht;c->input.append(buf,n);if(!drive(c))return;if(c->state!=0)break;continue;}if(n==0){closeclient(c);return;}if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK)break;closeclient(c);return;}}if(ev&EPOLLOUT){while(c->outpos<c->output.size()){ssize_t n=send(c->fd,c->output.data()+c->outpos,c->output.size()-c->outpos,MSG_NOSIGNAL);if(n>0){c->outpos+=n;c->write_deadline=nowms()+cfg.wt;continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))break;closeclient(c);return;}if(c->outpos==c->output.size()&&c->fileleft){while(c->fileleft){size_t chunk=(size_t)min<unsigned long long>(c->fileleft,1048576);ssize_t n=sendfile(c->fd,c->file,&c->fileoff,chunk);if(n>0){c->fileleft-=n;c->write_deadline=nowms()+cfg.wt;continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))break;closeclient(c);return;}if(!c->fileleft&&c->file>=0){close(c->file);c->file=-1;}}if(c->outpos==c->output.size()){c->output.clear();c->outpos=0;}if(!drive(c))return;}if(ev&(EPOLLERR|EPOLLHUP)){closeclient(c);return;}if((ev&EPOLLRDHUP)&&c->state==0){closeclient(c);return;}updateclient(c);}
int main(int argc,char**argv){signal(SIGPIPE,SIG_IGN);if(argc!=3||string(argv[1])!="--config"||!config(argv[2]))return 1;int listener=socket(cfg.la.ss_family,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(listener<0)return 1;int one=1;setsockopt(listener,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));if(bind(listener,(sockaddr*)&cfg.la,cfg.ll)||listen(listener,4096))return 1;ep=epoll_create1(EPOLL_CLOEXEC);if(ep<0)return 1;regfd(listener,0,EPOLLIN);epoll_event events[512];long long last=nowms();for(;;){int n=epoll_wait(ep,events,512,50);if(n<0){if(errno==EINTR)continue;break;}for(int i=0;i<n;i++){uint64_t id=events[i].data.u64;if(!id){for(;;){int fd=accept4(listener,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);if(fd<0){if(errno==EINTR)continue;break;}if((int)clients.size()>=cfg.maxconn){close(fd);continue;}Client*c=new Client;c->fd=fd;c->id=seq++;c->deadline=nowms()+cfg.idle;clients[fd]=c;nodes[c->id]={true,c};regfd(fd,c->id,EPOLLIN|EPOLLRDHUP);}continue;}auto it=nodes.find(id);if(it==nodes.end())continue;if(it->second.client)cliente((Client*)it->second.p,events[i].events);else upevent((Up*)it->second.p,events[i].events);}long long now=nowms();if(now-last>=25){last=now;vector<uint64_t> expired;for(auto &kv:clients){Client*c=kv.second;if((c->state==0&&now>=c->deadline)||((c->outpos<c->output.size()||c->fileleft)&&now>=c->write_deadline))expired.push_back(c->id);}for(auto id:expired){auto it=nodes.find(id);if(it!=nodes.end())closeclient((Client*)it->second.p);}expired.clear();for(auto &kv:ups)if(now>=kv.second->deadline)expired.push_back(kv.second->id);for(auto id:expired){auto it=nodes.find(id);if(it!=nodes.end())upfail((Up*)it->second.p);}}}return 0;}
